window.NOTES = [{"id": "muuluhdf-9x31", "recipeId": "haewol-fragrant-bouquet-ver2_r1", "rating": 3, "memo": "2분 49초 드로다운, 1:15.2 비율.\n첫번째 가수 안하고 나는 향은 꽃향기인데 하얀 꽃 향기인지는 잘 모르겠음.\n훌루훌루 센서리 잔에 마셨음.\n바이패스는 하지 않음.\n센서리 잔에서 살짝 식혀지니까 레몬 뉘앙스 있음. 향이 약하고 묽은 느낌.\n식으면 식을 수로 레몬 뉘앙스의 산미가 더 올라옴. 식어도 향이 있긴 있는데 여전히 약한 느낌.\n가볍게 먹을 수 있어서 좋긴한데 향이 약해서 아쉬움. 조금 더 진하고 향이 더 팡팡 터졌으면 좋겠음.\n식으니까 더 맛이 있음. 식었을 때 향이 코로 올라오는게 아니라 입안에서 향이 나는 듯한 느낌.", "date": "2026-10-05 11:02"}];
